  data: unknown,
  schema: { required: string[] },
): ValidationResult {
  if (typeof data !== "object" || data === null) {
    return { valid: false, errors: ["Input must be an object"] }
  }
  const obj = data as Record<string, unknown>
  const errors: string[] = []
