    // BUG: !obj[field] rejects falsy-but-valid values (0, "", false)
    // Fix: use !(field in obj) || obj[field] === undefined
    if (!obj[field]) {
      errors.push(`Missing required field: ${field}`)
    }
  }
  return { valid: errors.length === 0, errors }
}

